window.VoceDemoData = function () {
  'use strict';
  const d = JSON.parse(JSON.stringify(BASE)), now = new Date();
  const iso = off => { const x = new Date(now.getFullYear(), now.getMonth(), now.getDate() + off); if (off) while (x.getDay() === 0 || x.getDay() === 6) x.setDate(x.getDate() + 1); return `${x.getFullYear()}-${String(x.getMonth() + 1).padStart(2, '0')}-${String(x.getDate()).padStart(2, '0')}`; };
  d.exams.forEach(e => {
    e.date = iso(e._off || 0);
    if (e._live) {
      /* Beginn so legen, dass die letzte (noch offene) Gruppe gerade seit 5 Minuten läuft – mit dem Zeitplan der App (inkl. Pausen) */
      const hm = m => `${String(Math.floor(m / 60)).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}`;
      e.start = '00:00'; let off = 65;
      try { if (typeof schedule === 'function') { const sch = schedule(e); const last = sch[sch.length - 1]; if (last) off = last.start - sch[0].start + 5 + (sch[0].start || 0); } } catch (err) {}
      e.start = hm(Math.max(0, Math.floor((now.getHours() * 60 + now.getMinutes() - off) / 5) * 5));
    }
    delete e._off; delete e._live;
  });
  return JSON.stringify(d);
};
